      const item = applyMessage(store, raw);
      expect(item.outcome).toBe("sin-producto");
70→      stores.push(item.parsed?.store);
    }
    expect(stores).toEqual(["amazon", "mercadolibre", "ebay", "alibaba", "homecenter"]);
    store.close();
  });
});

